// VerifyCloud simulation harness for Verilator models.
//
// Replaces the main() generated by `verilator --binary` so that a run always
// ends in a controlled way and its evidence is preserved:
//   * $stop / $fatal / failed assertions end the simulation cleanly
//     (fatalOnError(false)) instead of std::abort(), so coverage and the
//     waveform are still written for failing tests;
//   * coverage is written to +vc_coverage=<file> (default coverage.dat);
//   * a VCD waveform is written when +vc_trace=<file> is given (model must be
//     built with --trace);
//   * the last line is a machine-readable summary:
//       VC_SIM_END finish=<0|1> error=<0|1> time=<sim time> timeunit=<exp>
// Exit status: 0 = $finish without error, 1 = error ($stop/$fatal/assertion),
//              3 = no $finish (event queue ran dry).
//
// Build: write vc_top.h into the Verilator output directory (-Mdir):
//          #include "Vtop.h"
//          #define VC_TOP Vtop
//        then: verilator ... --exe vc_main.cpp
// (a generated header avoids passing include names through make and a shell)
#include <cstdio>
#include <cstring>
#include <memory>
#include <string>

#include "verilated.h"
#include "vc_top.h"
#if VM_COVERAGE
#include "verilated_cov.h"
#endif
#if VM_TRACE
#include "verilated_vcd_c.h"
#endif

static std::string plusarg(VerilatedContext* ctx, const char* name) {
    // commandArgsPlusMatch returns the whole "+name=value" argument or "".
    const std::string prefix = std::string("+") + name;
    const char* m = ctx->commandArgsPlusMatch(name);
    if (!m || !*m) return "";
    std::string s(m);
    if (s.rfind(prefix, 0) != 0) return "";
    return s.substr(prefix.size());
}

int main(int argc, char** argv) {
    const std::unique_ptr<VerilatedContext> ctx{new VerilatedContext};
    ctx->commandArgs(argc, argv);
    ctx->fatalOnError(false);  // $stop/$fatal: finish cleanly, keep evidence
    ctx->traceEverOn(true);
    const std::unique_ptr<VC_TOP> top{new VC_TOP{ctx.get()}};

#if VM_TRACE
    std::unique_ptr<VerilatedVcdC> tfp;
    const std::string trace_file = plusarg(ctx.get(), "vc_trace=");
    if (!trace_file.empty()) {
        tfp.reset(new VerilatedVcdC);
        top->trace(tfp.get(), 99);
        tfp->open(trace_file.c_str());
    }
#endif

    while (!ctx->gotFinish()) {
        top->eval();
#if VM_TRACE
        if (tfp) tfp->dump(ctx->time());
#endif
        if (!top->eventsPending()) break;
        ctx->time(top->nextTimeSlot());
    }
    top->final();

#if VM_TRACE
    if (tfp) tfp->close();
#endif
#if VM_COVERAGE
    std::string cov_file = plusarg(ctx.get(), "vc_coverage=");
    if (cov_file.empty()) cov_file = "coverage.dat";
    ctx->coveragep()->write(cov_file.c_str());
#endif
    const bool finished = ctx->gotFinish();
    const bool error = ctx->gotError();
    std::printf("VC_SIM_END finish=%d error=%d time=%llu timeunit=%d\n", finished ? 1 : 0, error ? 1 : 0,
                static_cast<unsigned long long>(ctx->time()), static_cast<int>(ctx->timeprecision()));
    std::fflush(stdout);
    if (error) return 1;
    return finished ? 0 : 3;
}
